-- Step 3 (Import + Export): import batches, documents, extracted fields with provenance, review
-- decisions and document -> claim links; ClaimStatus AWAITING_ANALYSIS.
-- Generated by `prisma migrate diff` and hand-extended (security section at the end): CHECK constraints,
-- row-level security (fail closed), least-privilege grants for the runtime role, and append-only /
-- immutability triggers, following the pattern of 20261008000000_init. Run as freight_owner.
--
-- ClaimStatus gains AWAITING_ANALYSIS via ALTER TYPE ... ADD VALUE; nothing in this migration uses the
-- new value (it cannot be used inside the transaction that adds it).

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'freight_app') THEN
    RAISE EXCEPTION 'Role freight_app does not exist. Apply api/db/init/00-roles.sql as a superuser before running migrations.';
  END IF;
END
$$;

