-- ---------------------------------------------------------------------------------------------
-- CHECK constraints
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "import_batches" ADD CONSTRAINT "import_batches_label_length"
  CHECK (label IS NULL OR char_length(label) BETWEEN 1 AND 120);

ALTER TABLE "import_documents" ADD CONSTRAINT "import_documents_display_name_length"
  CHECK (char_length(display_name) BETWEEN 1 AND 255);
-- 1 byte .. the production ceiling of IMPORT_MAX_FILE_BYTES (25 MiB).
ALTER TABLE "import_documents" ADD CONSTRAINT "import_documents_size_range" CHECK (size_bytes BETWEEN 1 AND 26214400);
ALTER TABLE "import_documents" ADD CONSTRAINT "import_documents_sha256_hex" CHECK (sha256 ~ '^[0-9a-f]{64}$');
-- Object keys always live under the row's own tenant prefix.
ALTER TABLE "import_documents" ADD CONSTRAINT "import_documents_storage_key_tenant"
  CHECK (storage_key IS NULL OR storage_key LIKE 't/' || tenant_id::text || '/%');
ALTER TABLE "import_documents" ADD CONSTRAINT "import_documents_text_key_tenant"
  CHECK (text_key IS NULL OR text_key LIKE 't/' || tenant_id::text || '/%');
ALTER TABLE "import_documents" ADD CONSTRAINT "import_documents_stored_unless_rejected"
  CHECK (status IN ('REJECTED', 'FAILED') OR storage_key IS NOT NULL);
ALTER TABLE "import_documents" ADD CONSTRAINT "import_documents_uploader_for_uploads"
  CHECK (source = 'EMAIL' OR uploaded_by_id IS NOT NULL);
ALTER TABLE "import_documents" ADD CONSTRAINT "import_documents_source_ref_format"
  CHECK (source_ref IS NULL OR source_ref ~ '^[0-9a-f]{64}$');
ALTER TABLE "import_documents" ADD CONSTRAINT "import_documents_reject_reason"
  CHECK (reject_reason IS NULL OR (status IN ('REJECTED', 'FAILED') AND reject_reason ~ '^[a-z_]{1,40}$'));
ALTER TABLE "import_documents" ADD CONSTRAINT "import_documents_counts_nonneg"
  CHECK ((page_count IS NULL OR page_count >= 0) AND (char_count IS NULL OR char_count >= 0));
ALTER TABLE "import_documents" ADD CONSTRAINT "import_documents_load_number_length"
  CHECK (load_number IS NULL OR char_length(load_number) BETWEEN 1 AND 100);
ALTER TABLE "import_documents" ADD CONSTRAINT "import_documents_provider_strings"
  CHECK (char_length(provider_name) BETWEEN 1 AND 40 AND char_length(provider_version) BETWEEN 1 AND 20 AND char_length(parser_version) BETWEEN 1 AND 20);

-- The N7 field-key allow-list: anything else never appears.
ALTER TABLE "extracted_fields" ADD CONSTRAINT "extracted_fields_key_allowed" CHECK (key IN (
  'invoice.invoice_number', 'invoice.load_number', 'invoice.carrier', 'invoice.shipper', 'invoice.invoice_date',
  'invoice.total', 'invoice.charge.description', 'invoice.charge.amount',
  'rate_confirmation.load_number', 'rate_confirmation.carrier', 'rate_confirmation.linehaul_rate',
  'rate_confirmation.fuel_surcharge', 'rate_confirmation.detention_free_hours',
  'rate_confirmation.detention_rate_per_hour', 'rate_confirmation.detention_max_hours',
  'rate_confirmation.authorized_accessorials',
  'bol.load_number', 'bol.facility', 'bol.appointment_time', 'bol.arrival_time', 'bol.departure_time'));
-- Charge pairs (and only they) carry a group index.
ALTER TABLE "extracted_fields" ADD CONSTRAINT "extracted_fields_group_index"
  CHECK ((key IN ('invoice.charge.description', 'invoice.charge.amount')) = (group_index IS NOT NULL) AND (group_index IS NULL OR group_index >= 0));
ALTER TABLE "extracted_fields" ADD CONSTRAINT "extracted_fields_ordinal_nonneg" CHECK (ordinal >= 0);
ALTER TABLE "extracted_fields" ADD CONSTRAINT "extracted_fields_lengths"
  CHECK (char_length(raw_value) <= 500 AND (value IS NULL OR char_length(value) <= 4000)
         AND (corrected_value IS NULL OR char_length(corrected_value) <= 4000)
         AND (excerpt IS NULL OR char_length(excerpt) <= 200));
ALTER TABLE "extracted_fields" ADD CONSTRAINT "extracted_fields_confidence_range" CHECK (confidence BETWEEN 0 AND 1);
-- Provenance: pointer columns are all NULL iff the field was keyed in manually.
ALTER TABLE "extracted_fields" ADD CONSTRAINT "extracted_fields_pointer_iff_extracted" CHECK (
  (origin = 'MANUAL' AND page IS NULL AND line IS NULL AND start_col IS NULL AND end_col IS NULL AND source_row IS NULL AND excerpt IS NULL)
  OR (origin = 'EXTRACTED' AND line IS NOT NULL AND start_col IS NOT NULL AND end_col IS NOT NULL AND excerpt IS NOT NULL));
ALTER TABLE "extracted_fields" ADD CONSTRAINT "extracted_fields_pointer_ranges" CHECK (
  (page IS NULL OR page >= 1) AND (line IS NULL OR line >= 1) AND (source_row IS NULL OR source_row >= 1)
  AND (start_col IS NULL OR (start_col >= 0 AND end_col >= start_col)));
ALTER TABLE "extracted_fields" ADD CONSTRAINT "extracted_fields_corrected_iff_status"
  CHECK ((status = 'CORRECTED') = (corrected_value IS NOT NULL));
ALTER TABLE "extracted_fields" ADD CONSTRAINT "extracted_fields_resolution_iff_status"
  CHECK ((status = 'PROPOSED') = (resolved_at IS NULL) AND (resolved_at IS NULL) = (resolved_by_id IS NULL));
-- At most one LIVE field per (document, key, group); a NULL group counts as group 0. Rejected fields
-- leave the index so a reviewer can key in a replacement (R47).
CREATE UNIQUE INDEX "extracted_fields_one_live_per_key" ON "extracted_fields"
  ("document_id", "key", (COALESCE("group_index", 0))) WHERE status <> 'REJECTED';

ALTER TABLE "import_review_decisions" ADD CONSTRAINT "import_review_decisions_reason_length"
  CHECK (char_length(reason) BETWEEN 10 AND 2000);
ALTER TABLE "import_review_decisions" ADD CONSTRAINT "import_review_decisions_hashes_hex"
  CHECK ((before_value_sha256 IS NULL OR before_value_sha256 ~ '^[0-9a-f]{64}$')
         AND (after_value_sha256 IS NULL OR after_value_sha256 ~ '^[0-9a-f]{64}$'));
ALTER TABLE "import_review_decisions" ADD CONSTRAINT "import_review_decisions_field_actions"
  CHECK ((action IN ('CONFIRM', 'CORRECT', 'REJECT', 'ADD')) = (field_id IS NOT NULL));

