CREATE POLICY "extracted_fields_tenant_isolation" ON "extracted_fields" FOR ALL
  USING (tenant_id = fr_current_tenant()) WITH CHECK (tenant_id = fr_current_tenant());

ALTER TABLE "import_review_decisions" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "import_review_decisions" FORCE ROW LEVEL SECURITY;
CREATE POLICY "import_review_decisions_tenant_isolation" ON "import_review_decisions" FOR ALL
  USING (tenant_id = fr_current_tenant()) WITH CHECK (tenant_id = fr_current_tenant());

