-- ---------------------------------------------------------------------------------------------
-- Append-only and immutability triggers (fr_append_only comes from the init migration).
-- ---------------------------------------------------------------------------------------------
CREATE TRIGGER "import_batches_append_only" BEFORE UPDATE OR DELETE ON "import_batches" FOR EACH ROW EXECUTE FUNCTION fr_append_only();
CREATE TRIGGER "import_batches_no_truncate" BEFORE TRUNCATE ON "import_batches" FOR EACH STATEMENT EXECUTE FUNCTION fr_append_only();
CREATE TRIGGER "import_review_decisions_append_only" BEFORE UPDATE OR DELETE ON "import_review_decisions" FOR EACH ROW EXECUTE FUNCTION fr_append_only();
CREATE TRIGGER "import_review_decisions_no_truncate" BEFORE TRUNCATE ON "import_review_decisions" FOR EACH STATEMENT EXECUTE FUNCTION fr_append_only();
CREATE TRIGGER "claim_documents_append_only" BEFORE UPDATE OR DELETE ON "claim_documents" FOR EACH ROW EXECUTE FUNCTION fr_append_only();
CREATE TRIGGER "claim_documents_no_truncate" BEFORE TRUNCATE ON "claim_documents" FOR EACH STATEMENT EXECUTE FUNCTION fr_append_only();

-- Import documents: identity/content columns never change; status moves only along the pipeline
-- (RECEIVED -> NEEDS_REVIEW|ACCEPTED|REJECTED|FAILED, NEEDS_REVIEW -> ACCEPTED|REJECTED); terminal rows
-- (ACCEPTED, REJECTED, FAILED) are frozen; object keys may only be cleared when the row is rejected or
-- failed (object deleted), and the derived-text key may only be set once while the row is being parsed.
CREATE FUNCTION fr_import_document_update_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
     OR NEW.batch_id IS DISTINCT FROM OLD.batch_id OR NEW.uploaded_by_id IS DISTINCT FROM OLD.uploaded_by_id
     OR NEW.source IS DISTINCT FROM OLD.source OR NEW.source_ref IS DISTINCT FROM OLD.source_ref
     OR NEW.display_name IS DISTINCT FROM OLD.display_name OR NEW.detected_type IS DISTINCT FROM OLD.detected_type
     OR NEW.size_bytes IS DISTINCT FROM OLD.size_bytes OR NEW.sha256 IS DISTINCT FROM OLD.sha256
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'import_document_immutable' USING ERRCODE = 'P0001';
  END IF;
  IF OLD.status IN ('ACCEPTED', 'REJECTED', 'FAILED') THEN
    RAISE EXCEPTION 'import_document_terminal' USING ERRCODE = 'P0001';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status
     AND NOT ((OLD.status = 'RECEIVED' AND NEW.status IN ('NEEDS_REVIEW', 'ACCEPTED', 'REJECTED', 'FAILED'))
              OR (OLD.status = 'NEEDS_REVIEW' AND NEW.status IN ('ACCEPTED', 'REJECTED'))) THEN
    RAISE EXCEPTION 'invalid_import_document_transition' USING ERRCODE = 'P0001';
  END IF;
  IF NEW.storage_key IS DISTINCT FROM OLD.storage_key
     AND NOT (OLD.storage_key IS NOT NULL AND NEW.storage_key IS NULL AND NEW.status IN ('REJECTED', 'FAILED')) THEN
    RAISE EXCEPTION 'import_document_storage_key' USING ERRCODE = 'P0001';
  END IF;
  IF NEW.text_key IS DISTINCT FROM OLD.text_key
     AND NOT (OLD.text_key IS NULL AND NEW.text_key IS NOT NULL AND OLD.status = 'RECEIVED')
     AND NOT (OLD.text_key IS NOT NULL AND NEW.text_key IS NULL AND NEW.status IN ('REJECTED', 'FAILED')) THEN
    RAISE EXCEPTION 'import_document_text_key' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "import_documents_update_guard" BEFORE UPDATE ON "import_documents" FOR EACH ROW EXECUTE FUNCTION fr_import_document_update_guard();
CREATE TRIGGER "import_documents_no_delete" BEFORE DELETE ON "import_documents" FOR EACH ROW EXECUTE FUNCTION fr_append_only();
CREATE TRIGGER "import_documents_no_truncate" BEFORE TRUNCATE ON "import_documents" FOR EACH STATEMENT EXECUTE FUNCTION fr_append_only();

-- Extracted fields: only the resolution columns may change, exactly once (PROPOSED -> resolved).
CREATE FUNCTION fr_extracted_field_update_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF (to_jsonb(NEW) - 'status' - 'corrected_value' - 'resolved_by_id' - 'resolved_at')
     IS DISTINCT FROM (to_jsonb(OLD) - 'status' - 'corrected_value' - 'resolved_by_id' - 'resolved_at') THEN
    RAISE EXCEPTION 'extracted_field_immutable' USING ERRCODE = 'P0001';
  END IF;
  IF NOT (OLD.status = 'PROPOSED' AND NEW.status IN ('CONFIRMED', 'CORRECTED', 'REJECTED')) THEN
    RAISE EXCEPTION 'invalid_extracted_field_transition' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "extracted_fields_update_guard" BEFORE UPDATE ON "extracted_fields" FOR EACH ROW EXECUTE FUNCTION fr_extracted_field_update_guard();
CREATE TRIGGER "extracted_fields_no_delete" BEFORE DELETE ON "extracted_fields" FOR EACH ROW EXECUTE FUNCTION fr_append_only();
CREATE TRIGGER "extracted_fields_no_truncate" BEFORE TRUNCATE ON "extracted_fields" FOR EACH STATEMENT EXECUTE FUNCTION fr_append_only();

-- ---------------------------------------------------------------------------------------------
-- Least-privilege grants for the runtime role (no TRUNCATE, no DELETE, no DDL). Enum types keep the
-- PostgreSQL default USAGE for PUBLIC (as in the init migration).
-- ---------------------------------------------------------------------------------------------
REVOKE ALL ON "import_batches", "import_documents", "extracted_fields", "import_review_decisions", "claim_documents" FROM PUBLIC;
REVOKE ALL ON FUNCTION fr_import_document_update_guard() FROM PUBLIC;
REVOKE ALL ON FUNCTION fr_extracted_field_update_guard() FROM PUBLIC;
GRANT SELECT, INSERT ON "import_batches", "import_review_decisions", "claim_documents" TO freight_app;
GRANT SELECT, INSERT ON "import_documents" TO freight_app;
GRANT UPDATE ("status", "reject_reason", "review_reasons", "warnings", "doc_type", "doc_type_basis", "page_count",
              "char_count", "load_number", "text_key", "provider_name", "provider_version", "parser_version",
              "storage_key", "parsed_at", "updated_at") ON "import_documents" TO freight_app;
GRANT SELECT, INSERT ON "extracted_fields" TO freight_app;
GRANT UPDATE ("status", "corrected_value", "resolved_by_id", "resolved_at") ON "extracted_fields" TO freight_app;
